import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Badge,
  Card,
  Table,
  Container,
  Row,
  Col,
  Modal,      // เพิ่มตัวนี้
  Button      // เพิ่มตัวนี้
} from "react-bootstrap";

function Dashboard() {
  const [tableData, setTableData] = useState([]);
  const [chartData, setChartData] = useState({ labels: [], series: [] });
  const [stats, setStats] = useState({ busStops: 0, cameras: "Active", alerts: 0, users: 0 });

  // --- 1. เพิ่ม State สำหรับจัดการ Modal ---
  const [showModal, setShowModal] = useState(false);
  const [selectedStation, setSelectedStation] = useState(null);

  // ฟังก์ชันเมื่อกดเลือกสถานี
  const handleViewDetails = (station) => {
    setSelectedStation(station);
    setShowModal(true);
  };

  const fetchData = async () => {
    try {
      const statsRes = await fetch('http://localhost:3000/api/dashboard-stats');
      const statsJson = await statsRes.json();
      setStats({
        busStops: statsJson.capacity,
        cameras: statsJson.revenue,
        alerts: statsJson.errors,
        users: statsJson.followers
      });

      const tableRes = await fetch('http://localhost:3000/api/table-data');
      const tableJson = await tableRes.json();
      setTableData(tableJson);

      const chartRes = await fetch('http://localhost:3000/api/chart-data');
      const chartJson = await chartRes.json();
      setChartData(chartJson);
    } catch (err) {
      console.error("Fetch Error:", err);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 30000);
    return () => clearInterval(interval);
  }, []);

  return (
    <Container fluid>
      {/* ส่วนที่ 1 & 2 (การ์ดและกราฟ) ให้คงเดิมไว้ */}
      {/* ... (Code ส่วน Row การ์ด และ Row กราฟ) ... */}

      {/* --- ส่วนที่ 3: ตารางที่คลิกได้ --- */}
      <Row>
        <Col md="12">
          <Card className="strpied-tabled-with-hover">
            <Card.Header>
              <Card.Title as="h4">Bus Stop Detail Table</Card.Title>
              <p className="card-category">คลิกที่แถวสถานีเพื่อดูรายละเอียดกล้อง CCTV</p>
            </Card.Header>
            <Card.Body className="table-full-width table-responsive px-0">
              <Table className="table-hover table-striped">
                <thead>
                  <tr>
                    <th className="border-0">ID</th>
                    <th className="border-0">Station Name</th>
                    <th className="border-0">Passenger</th>
                    <th className="border-0">Status</th>
                    <th className="border-0 text-right">Action</th>
                  </tr>
                </thead>
                <tbody>
                  {tableData.map((item, index) => (
                    <tr 
                      key={item.id || index} 
                      onClick={() => handleViewDetails(item)} 
                      style={{ cursor: "pointer" }} // ทำให้เมาส์เป็นรูปมือเมื่อชี้
                    >
                      <td>{item.id}</td>
                      <td>{item.stationName}</td>
                      <td>{item.passengerCount}</td>
                      <td>
                        <Badge bg={item.status === "Crowded" ? "danger" : "success"}>
                          {item.status}
                        </Badge>
                      </td>
                      <td className="text-right">
                        <Button variant="info" size="sm" className="btn-fill">
                          View Cameras
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* --- ส่วนที่ 4: Modal แสดงรายละเอียดกล้อง (Popup) --- */}
      <Modal
        show={showModal}
        onHide={() => setShowModal(false)}
        size="lg"
        centered
      >
        <Modal.Header closeButton>
          <Modal.Title id="example-modal-sizes-title-lg">
            Station Details: {selectedStation?.stationName}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Row>
            <Col md="12">
              <h5>Camera Feeds List</h5>
              <Table borderless hover>
                <thead>
                  <tr>
                    <th>Camera ID</th>
                    <th>Position</th>
                    <th>Status</th>
                    <th>Live Stream</th>
                  </tr>
                </thead>
                <tbody>
                  {/* ในที่นี้เราจำลองข้อมูลกล้อง 2 ตัวต่อสถานี */}
                  <tr>
                    <td>CAM-01</td>
                    <td>Entrance (ทางเข้า)</td>
                    <td><Badge bg="success">Online</Badge></td>
                    <td><Button variant="outline-primary" size="sm">Open Stream</Button></td>
                  </tr>
                  <tr>
                    <td>CAM-02</td>
                    <td>Platform (ชานชาลา)</td>
                    <td><Badge bg="success">Online</Badge></td>
                    <td><Button variant="outline-primary" size="sm">Open Stream</Button></td>
                  </tr>
                </tbody>
              </Table>
            </Col>
          </Row>
          <hr />
          <div className="text-center p-3 bg-dark text-light rounded">
             <i className="nc-icon nc-zoom-split mr-2"></i>
             [ พื้นที่แสดงภาพจากกล้อง CCTV ของสถานี {selectedStation?.stationName} ]
          </div>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Close
          </Button>
        </Modal.Footer>
      </Modal>

    </Container>
  );
}

export default Dashboard;
